      if (diagnosi.leggibili['gruppo.massimo']) c.gMassimo = numeroMB(leggiPiccolo(g.massimo));
      if (diagnosi.leggibili['gruppo.volte']) { x = parseInt(leggiPiccolo(g.volte), 10); c.gVolte = isFinite(x) ? x : null; }
